def gallery_page(building, files):
    base = f'assets/projects/sketchup/{building}/'
    cards = ''.join(f'<button class="shot" type="button" data-index="{i}"><img src="{escape(base+name)}" alt="SKETCHUP {building.replace("-", " ").title()} image {i+1}" loading="lazy"></button>' for i,name in enumerate(files))
    jsfiles = ','.join(repr(base+n) for n in files)
    title = 'Building 01' if building == 'building-01' else 'Building 02'
    ar = 'المبنى 01' if building == 'building-01' else 'المبنى 02'
    return f'''<!doctype html><html lang="en" dir="ltr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#07111f"><meta name="description" content="SKETCHUP {title} gallery by Komail Alsenan."><link rel="canonical" href="https://komail-alsenan.github.io/portfolio/sketchup-{building}.html"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/css/main.css"><title>SKETCHUP · {title} | Komail Alsenan</title><style>:root{{--bg:#050b14;--text:#edf6ff;--muted:#96a9bd;--cyan:#4cd7ff;--line:rgba(118,180,255,.16)}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--text);font-family:Inter,"Segoe UI",Tahoma,Arial,sans-serif;line-height:1.65}}.container{{width:min(1120px,calc(100% - 40px));margin:auto}}a{{color:inherit;text-decoration:none}}.nav{{border-bottom:1px solid var(--line);background:#07111f}}.nav-inner{{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:12px}}.hero{{padding:54px 0 24px}}.kicker{{color:var(--cyan);font-weight:800;letter-spacing:1.2px}}.hero h1{{font-size:clamp(2.8rem,7vw,5rem);line-height:1;margin:10px 0 14px}}.hero p{{color:var(--muted);max-width:760px}}.gallery{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding:16px 0 72px}}.shot{{padding:0;border:1px solid var(--line);border-radius:16px;overflow:hidden;background:#0b1627;cursor:zoom-in;aspect-ratio:4/3}}.shot img{{width:100%;height:100%;object-fit:cover;display:block}}.viewer{{position:fixed;inset:0;z-index:100;display:none;place-items:center;background:rgba(2,7,14,.94);padding:max(18px,env(safe-area-inset-top)) max(18px,env(safe-area-inset-right)) max(18px,env(safe-area-inset-bottom)) max(18px,env(safe-area-inset-left))}}.viewer.open{{display:grid}}.viewer img{{max-width:min(94vw,1600px);max-height:88dvh;object-fit:contain}}.viewer button{{position:absolute;border:1px solid var(--line);background:#0b1627;color:#fff;border-radius:12px;min-width:46px;min-height:46px;cursor:pointer}}.close{{top:18px;right:18px}}.prev{{left:18px;top:50%}}.next{{right:18px;top:50%}}.count{{position:absolute;bottom:18px;color:#dbeaff;font-weight:700}}.footer{{border-top:1px solid var(--line);padding:28px 0;color:var(--muted)}}html[dir="rtl"] body{{font-family:Tahoma,"Segoe UI",Arial,sans-serif}}@media(max-width:850px){{.gallery{{grid-template-columns:repeat(2,minmax(0,1fr))}}}}@media(max-width:560px){{.container{{width:min(100% - 26px,1120px)}}.gallery{{grid-template-columns:1fr}}.nav-inner{{min-height:62px}}}}</style></head><body><nav class="nav"><div class="container nav-inner"><a href="sketchup.html">← SKETCHUP</a><button class="pg-btn pg-lang" type="button" data-pg-lang aria-pressed="false">العربية</button></div></nav><main><section class="hero"><div class="container"><span class="kicker">SKETCHUP · {title.upper()}</span><h1 data-en="{title}" data-ar="{ar}">{title}</h1><p data-en="SketchUp model and architectural presentation gallery." data-ar="معرض نموذج SketchUp والإظهار المعماري.">SketchUp model and architectural presentation gallery.</p></div></section><div class="container"><section class="gallery" data-sketchup-gallery="{building}" aria-label="{title} image gallery">{cards}</section></div></main><div class="viewer" id="viewer" role="dialog" aria-modal="true" aria-label="Image viewer"><button class="close" type="button" aria-label="Close">×</button><button class="prev" type="button" aria-label="Previous">‹</button><img id="viewerImg" alt=""><button class="next" type="button" aria-label="Next">›</button><div class="count" id="viewerCount"></div></div><footer class="footer"><div class="container">© <span id="year"></span> Komail Jaffar Al Senan · Architecture BIM Modeler</div></footer><script>const images=[{jsfiles}];let current=0;const viewer=document.getElementById('viewer'),img=document.getElementById('viewerImg'),count=document.getElementById('viewerCount');function show(i){{current=(i+images.length)%images.length;img.src=images[current];img.alt='{title} image '+(current+1);count.textContent=(current+1)+' / '+images.length;viewer.classList.add('open');document.body.style.overflow='hidden'}}function closeViewer(){{viewer.classList.remove('open');document.body.style.overflow=''}}document.querySelectorAll('.shot').forEach((b,i)=>b.addEventListener('click',()=>show(i)));viewer.querySelector('.close').onclick=closeViewer;viewer.querySelector('.prev').onclick=()=>show(current-1);viewer.querySelector('.next').onclick=()=>show(current+1);viewer.addEventListener('click',e=>{{if(e.target===viewer)closeViewer()}});document.addEventListener('keydown',e=>{{if(!viewer.classList.contains('open'))return;if(e.key==='Escape')closeViewer();if(e.key==='ArrowLeft')show(current-1);if(e.key==='ArrowRight')show(current+1)}});document.getElementById('year').textContent=new Date().getFullYear()</script><script src="assets/js/project-gallery.js"></script><script src="assets/js/project-image-protection.js"></script><script src="assets/js/main.js" defer></script></body></html>'''

